import { attachOrUnavailable, isAttached, type CommandContext } from './shared';
import { invalidateAttachCache, type AttachedServer } from '../client';
import { serverVersionInfo, versionEnvelopeFields } from '../serverVersion';
import { ensureProjectRuntime, type ProjectRuntimeDependencies } from './open';
import { errorResult, type CliCommandResult } from '../envelope';
import type { CliIO } from '../io';

export const preflightGeneration = async ({
  command,
  context,
  io,
  dependencies,
}: {
  command: string;
  context: CommandContext;
  io: CliIO;
  dependencies?: ProjectRuntimeDependencies;
}): Promise<AttachedServer | CliCommandResult> => {
  invalidateAttachCache();
  let attached = await attachOrUnavailable(command, context.projectPath);
  if (
    !isAttached(attached) ||
    !serverVersionInfo(attached.handshake).staleServer
  )
    return attached;
  const opened = await ensureProjectRuntime(context, io, dependencies);
  if (!opened.envelope.ok)
    return { ...opened, envelope: { ...opened.envelope, command } };
  invalidateAttachCache();
  attached = await attachOrUnavailable(command, context.projectPath);
  if (!isAttached(attached)) return attached;
  if (!serverVersionInfo(attached.handshake).staleServer) return attached;
  const data = opened.envelope.data as { upgrade?: { message?: string } };
  return errorResult(
    command,
    'SERVER_UNAVAILABLE',
    data.upgrade?.message ??
      'This project server must be upgraded before generation. Run `rivet open` to restart it and retry interrupted work.',
    {
      serverUnavailableReason: 'server_upgrade_required',
      ...versionEnvelopeFields(attached.handshake),
      upgrade: data.upgrade,
    },
    {
      isRecoverable: true,
      nextAction: {
        action: 'open_project',
        command: 'rivet open',
        args: ['--project', context.projectPath],
      },
    },
  );
};
